L000129	\centering
L000130	\includegraphics[width=0.88\linewidth]{Fig1.pdf}
L000131	\caption{
L000132	Schematic phase diagrams of (a) water and (b) \nbwo, where the solid line represents a first-order transition and the red star denotes the critical endpoint (CEP). The dashed lines enclose the Ising supercritical regime (ISR). The universal supercritical crossover scaling is $\delta \hat{P}^{\pm}\propto t^{\beta+\gamma}$ for water~\cite{li2024supfluid}, and $h\propto t^{\beta+\gamma}$ for \nbwo\ ($\delta\hat{P}^{\pm}$, $t$ and $h$ being reduced parameters). $\beta$ and $\gamma$ are the critical exponents of the 3D Ising universality class. (c) Coupled Ising tubes formed by Nd$^{3+}$ ions and distorted NdO$_8$ octahedra. (d-f) Schematic magnetization curves above, at, and below $T_{\rm c}$.
L000133	}
L000134	\label{fig1}
L000135	\end{figure}
